# export PROTO_LOSS_GROUP_FILE=/absolute/path/to/fixed_groups.json
# export PROTO_LOSS_REUSE_GROUP_FILE=1
if [[ "${PROTO_LOSS_REUSE_GROUP_FILE:-0}" == "1" ]]; then
    PROTO_LOSS_OLD_GROUP_ARG="--multi_group_publish '$PROTO_LOSS_GROUP_FILE'"
    PROTO_LOSS_NEW_GROUP_ARG="--multi_group_file '$PROTO_LOSS_GROUP_FILE' --multi_group_wait_seconds $PROTO_LOSS_GROUP_WAIT --multi_group_poll_seconds 1"
    COMMANDS[0]="${COMMANDS[0]/"$PROTO_LOSS_OLD_GROUP_ARG"/"$PROTO_LOSS_NEW_GROUP_ARG"}"
fi
